/**
 * sw.js — Shree Royal Car BMS Service Worker
 * ─────────────────────────────────────────────────────────────────────────────
 * Caching strategies:
 *
 *  /_next/static/**   Cache-First   (immutable hashed chunks)
 *  Navigation HTML    Network-First (get updates; fall back to cache offline)
 *  /fonts /images     Cache-First
 *  /api/**            Network-Only  (never cache API/auth responses)
 *  Supabase URLs      Network-Only
 *
 * On install:
 *  1. Fetches /sw-precache.json (generated by scripts/generate-sw-precache.mjs
 *     after `next build`) to get the list of hashed JS/CSS chunks.
 *  2. Pre-caches those chunks + the main app shell pages.
 *
 * This gives true offline navigation — the browser can reconstruct any
 * cached page entirely from local assets + IndexedDB data.
 */

const CACHE_NAME  = "src-bms-v3";
const OFFLINE_URL = "/offline.html";

const SHELL_PAGES = [
  "/",
  "/billing",
  "/customers",
  "/finance",
  "/workers",
  "/profile",
  "/offline.html",
];

// ─── Install ──────────────────────────────────────────────────────────────────

self.addEventListener("install", (event) => {
  event.waitUntil(installCache());
});

async function installCache() {
  const cache = await caches.open(CACHE_NAME);

  // 1. Fetch the generated precache manifest (list of hashed Next.js chunks)
  let builtAssets = [];
  try {
    const res = await fetch("/sw-precache.json?t=" + Date.now());
    if (res.ok) {
      const json = await res.json();
      builtAssets = json.assets || [];
    }
  } catch (e) {
    console.warn("[SW] Could not fetch sw-precache.json:", e.message);
  }

  // 2. Pre-cache everything — shell pages + built chunks
  const all = [...new Set([...SHELL_PAGES, ...builtAssets])];
  await Promise.allSettled(
    all.map((url) =>
      cache.add(url).catch((e) => {
        // Non-fatal — log and continue
        if (!url.includes("sw-precache")) {
          console.warn("[SW] precache failed:", url, e.message);
        }
      })
    )
  );

  await self.skipWaiting();
}

// ─── Activate ─────────────────────────────────────────────────────────────────

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
      )
      .then(() => self.clients.claim())
  );
});

// ─── Fetch ────────────────────────────────────────────────────────────────────

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== "GET") return;

  // Never intercept: Supabase, API routes, HMR, chrome-extension
  if (
    url.hostname.includes("supabase.co") ||
    url.pathname.startsWith("/api/") ||
    url.protocol === "chrome-extension:" ||
    url.pathname.includes("_next/webpack-hmr") ||
    url.pathname.includes("__nextjs")
  ) {
    return;
  }

  // Immutable hashed static chunks — cache forever
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Static assets
  if (
    url.pathname.startsWith("/fonts/") ||
    url.pathname.match(/\.(ico|png|jpg|jpeg|svg|webp|woff2?|ttf|otf)$/)
  ) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // HTML navigation + everything else on our origin
  if (url.origin === self.location.origin) {
    event.respondWith(networkFirstWithFallback(request));
  }
});

// ─── Strategies ───────────────────────────────────────────────────────────────

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response.ok || response.status === 0) {
      const cache = await caches.open(CACHE_NAME);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    return new Response("", { status: 408 });
  }
}

async function networkFirstWithFallback(request) {
  try {
    const response = await fetch(request);
    if (response.ok || response.status === 0) {
      const cache = await caches.open(CACHE_NAME);
      cache.put(request, response.clone());
      return response;
    }
    throw new Error(`HTTP ${response.status}`);
  } catch {
    const cached = await caches.match(request);
    if (cached) return cached;

    // Try root shell
    const root = await caches.match("/");
    if (root) return root;

    const offline = await caches.match(OFFLINE_URL);
    if (offline) return offline;

    return new Response(
      "<h1>Offline</h1><p>Open the app while connected first to enable offline access.</p>",
      { status: 503, headers: { "Content-Type": "text/html" } }
    );
  }
}
